#!/usr/bin/env python3
"""Generate os/src/text/encoding_data.inc from the WHATWG Encoding Standard indexes and the
Unicode CP437/CP850 vendor mappings.  Usage: gen_encodings.py <index-dir> <out.inc>"""
import sys, os
D, OUT = sys.argv[1], sys.argv[2]
def index(name):
    m = {}
    for l in open(os.path.join(D, f'index-{name}.txt'), encoding='utf-8'):
        l = l.split('#')[0].strip()
        if not l: continue
        p, c = l.split()[:2]; m[int(p)] = int(c, 16)
    return m
def vendor(name):
    m = {}
    for l in open(os.path.join(D, name), encoding='latin-1'):
        l = l.split('#')[0].strip()
        if not l: continue
        f = l.split()
        if len(f) < 2: continue
        a, b = f[:2]
        if int(a, 16) >= 0x80: m[int(a, 16) - 0x80] = int(b, 16)
    return m
SB = ['windows-874', 'windows-1250', 'windows-1251', 'windows-1252', 'windows-1253', 'windows-1254', 'windows-1255', 'windows-1256',
      'windows-1257', 'windows-1258', 'iso-8859-2', 'iso-8859-3', 'iso-8859-4', 'iso-8859-5', 'iso-8859-6', 'iso-8859-7', 'iso-8859-8',
      'iso-8859-10', 'iso-8859-13', 'iso-8859-14', 'iso-8859-15', 'iso-8859-16', 'koi8-r', 'koi8-u', 'ibm866', 'macintosh']
o = open(OUT, 'w'); w = o.write
w('// Generated by tools/unicode/gen_encodings.py from the WHATWG Encoding Standard indexes (CC BY 4.0)\n')
w('// and Unicode vendor mappings CP437/CP850. Do not edit.\nnamespace forge::os::text::encdata {\n')
def arr(t, name, vals, per=20):
    w(f'inline constexpr {t} {name}[{len(vals)}] = {{\n')
    for i in range(0, len(vals), per): w(','.join(str(x) for x in vals[i:i + per]) + ',\n')
    w('};\n')
names = SB + ['ibm437', 'ibm850']
tabs = [index(n) for n in SB] + [vendor('CP437.TXT'), vendor('CP850.TXT')]
w('inline constexpr const char* single_byte_names[%d] = {%s};\n' % (len(names), ','.join('"%s"' % n for n in names)))
flat = []
for t in tabs: flat += [t.get(i, 0) for i in range(128)]
arr('unsigned short', 'single_byte', flat, 32)
def dense(name, ctype='unsigned short'):
    m = index(name); n = max(m) + 1
    arr(ctype, name.replace('-', '_'), [m.get(i, 0) for i in range(n)], 24)
dense('jis0208'); dense('jis0212'); dense('gb18030'); dense('euc-kr'); dense('big5', 'unsigned')
r = []
for l in open(os.path.join(D, 'index-gb18030-ranges.txt')):
    l = l.split('#')[0].strip()
    if l: p, c = l.split()[:2]; r += [int(p), int(c, 16)]
arr('unsigned', 'gb18030_ranges', r)
w('}  // namespace forge::os::text::encdata\n'); o.close()
print(os.path.getsize(OUT))
